let isFirstFunctionActive = false;

function debouncedFirstFunction() {
if (!isFirstFunctionActive) {
isFirstFunctionActive = true;
// Do something here
setTimeout(() => {
isFirstFunctionActive = false;
}, debounceTimeout);
}
}

function debouncedSecondFunction() {
