public static double calculateLaneVolatility(double[] gold, double[] level, int[] items, int numMinutes, double w1, double w2, double w3) {
    double goldMean = calculateMean(gold);
    double levelMean = calculateMean(level);
    double itemsMean = calculateMean(items);

    double goldVariance = calculateVariance(gold, goldMean);
    double levelVariance = calculateVariance(level, levelMean);
    double itemsVariance = calculateVariance(items, itemsMean);

